#!/usr/bin/env python3
"""Allowlisted, dependency-free bilingual static export and portable source kit."""
from pathlib import Path
import hashlib,html,json,shutil,zipfile
ROOT=Path(__file__).resolve().parents[1];BASE='/distributed-systems-lab';ORIGIN='https://lynnlee1229.github.io'
COURSE=json.loads((ROOT/'course.json').read_text())
OUT=ROOT/'build/site'/BASE.lstrip('/')
def esc(s):return html.escape(str(s),quote=True)
def L(lang,en,zh):return zh if lang=='zh' else en
TITLES={x['slug']:{l:x[l] for l in ('en','zh')} for x in COURSE}
TITLES.update({'index':{'en':'Distributed Systems Lab','zh':'分布式系统学习 Lab'},'reproduce':{'en':'Reproduce the real experiments','zh':'复现真实实验'},'checker':{'en':'History workbench','zh':'历史检查台'},'evidence':{'en':'Real experiment evidence','zh':'真实实验证据'},'references':{'en':'Sources & scope','zh':'来源与范围'}})
def url(lang,slug):return f'{ORIGIN}{BASE}/{lang}/'+('' if slug=='index' else slug+'.html')
def nav(lang,slug):
    links=''.join(f'<a class="{"active" if slug==x["slug"] else ""}" href="{x["slug"]}.html">{i+1:02} · {esc(x[lang])}</a>' for i,x in enumerate(COURSE))
    extra=''.join(f'<a href="{s}.html">{esc(TITLES[s][lang])}</a>' for s in ('checker','evidence','reproduce','references'))
    return f'<aside class="side"><p class="side-label">{L(lang,"LEARNING PATH","学习路线")}</p><nav aria-label="{L(lang,"Chapters","章节")}">{links}</nav><div class="aux">{extra}</div></aside>'
def frame(lang,slug,body):
    other='zh' if lang=='en' else 'en';title=TITLES[slug][lang];locale='zh-CN' if lang=='zh' else 'en-US';file='index.html' if slug=='index' else slug+'.html'
    desc=L(lang,'A foundation-first course on delay, failure and concurrency. Seven chapters, real etcd experiments, bounded history checks and reproducible evidence.','从延迟、故障与并发出发的基础课程：七章讲解、真实 etcd 实验、有界历史检查与可复现证据。')
    head=f'''<!doctype html><html lang="{locale}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{esc(title)} · Distributed Systems Lab</title><meta name="description" content="{desc}"><meta name="color-scheme" content="light"><link rel="canonical" href="{url(lang,slug)}"><link rel="alternate" hreflang="en-US" href="{url('en',slug)}"><link rel="alternate" hreflang="zh-CN" href="{url('zh',slug)}"><link rel="alternate" hreflang="x-default" href="{url('en',slug)}"><link rel="stylesheet" href="../assets/style.css"><link rel="icon" href="../assets/icon.svg" type="image/svg+xml"></head><body><a class="skip" href="#main">{L(lang,'Skip to content','跳到正文')}</a><header class="top"><a class="brand" href="index.html"><em>DS / LAB</em> {L(lang,'Distributed Systems','分布式系统')}</a><nav aria-label="{L(lang,'Main','主导航')}"><a class="home-link" href="{ORIGIN}/{'zh/' if lang=='zh' else ''}websites/#learning-labs">{L(lang,'All Labs','全部 Lab')}</a><a href="evidence.html">{L(lang,'Evidence','实测证据')}</a><a href="reproduce.html">{L(lang,'Run locally','本地复现')}</a><a class="lang" lang="{'zh-CN' if other=='zh' else 'en-US'}" href="../{other}/{file}">{'中文' if other=='zh' else 'English'} ↗</a></nav></header>'''
    if slug=='index':main=f'<main id="main" class="shell">{body}</main>'
    else:
        idx=next((i for i,x in enumerate(COURSE) if x['slug']==slug),None)
        pager=''
        if idx is not None:
            prev=COURSE[idx-1]['slug'] if idx>0 else 'index';nxt=COURSE[idx+1]['slug'] if idx<6 else 'evidence'
            pager=f'<div class="pager"><a href="{prev}.html">← {esc(TITLES[prev][lang])}</a><a href="{nxt}.html">{esc(TITLES[nxt][lang])} →</a></div>'
        eyebrow=L(lang,'CHAPTER','章节')+f' {idx+1:02}' if idx is not None else L(lang,'METHODS & TOOLS','方法与工具')
        main=f'<main id="main" class="shell reading">{nav(lang,slug)}<article class="article"><div class="eyebrow">{eyebrow} / FIRST EDITION · ETCD 3.6.6</div><h1>{esc(title)}</h1>{body}{pager}</article></main>'
    foot=f'<footer class="footer"><span>Distributed Systems Lab · {L(lang,"Original course · MIT licensed","原创课程 · MIT 授权")} · 2026-11-14</span><span><a href="references.html">{L(lang,"Sources & boundaries","来源与边界")}</a> · <a href="https://github.com/lynnlee1229/distributed-systems-lab">{L(lang,"Companion source","配套源码")}</a></span></footer><script type="module" src="../assets/app.mjs"></script></body></html>'
    return head+main+foot

def home(lang):
    title=L(lang,'What survives<br>a <span>failure?</span>','发生<span>故障</span>时，<br>什么仍有保证？')
    intro=L(lang,'When messages arrive late, nodes stop and operations overlap, what can a system still promise? Build the model, inspect real experiments, then change the conditions yourself.','当消息延迟、节点停止、操作并发时，系统究竟还能承诺什么？先建立模型，再检查真实实验，最后亲手改变条件。')
    cards=''.join(f'<a class="path-card" href="{x["slug"]}.html"><span class="num">{i+1:02}</span><div><h3>{esc(x[lang])}</h3><p>{esc(x["summary_"+lang])}</p><small>{x["time"]} · {L(lang,"Suggested study time, not measured","建议学习时间，非测量值")}</small></div></a>' for i,x in enumerate(COURSE))
    net=f'''<div class="network"><svg viewBox="0 0 350 285" role="img" aria-label="{L(lang,'Three replicas with one paused node; two connected voters form a majority','三个副本中一个暂停，两个相连投票者组成多数派')}"><path d="M175 57 L65 205 L285 205 Z" stroke="#d7dcd2" stroke-width="2" fill="none" stroke-dasharray="5 7"/><path d="M175 57 L65 205" stroke="#386d70" stroke-width="3"/><circle cx="175" cy="57" r="34" fill="#1e2c2c"/><circle cx="65" cy="205" r="34" fill="#e0e9df" stroke="#386d70"/><circle cx="285" cy="205" r="34" fill="#f1ded3" stroke="#b84932"/><text x="175" y="63" text-anchor="middle" style="fill:white">n1</text><text x="65" y="211" text-anchor="middle">n2</text><text x="285" y="211" text-anchor="middle">Ⅱ</text><text x="175" y="112" text-anchor="middle" font-size="11">LEADER</text><text x="65" y="262" text-anchor="middle" font-size="11">FOLLOWER</text><text x="285" y="262" text-anchor="middle" font-size="11">PAUSED</text></svg><p>{L(lang,'ILLUSTRATION / 3 voters · quorum 2<br>Real process results are recorded separately.','原理示意 / 3 个投票者 · 多数派 2<br>真实进程结果单独保存。')}</p></div>'''
    tools=''.join(f'<div class="tool-card"><h3><a href="{s}.html">{esc(TITLES[s][lang])} ↗</a></h3><p>{txt}</p></div>' for s,txt in [('checker',L(lang,'Compare linearizable and sequential histories. Inspect a witness, a counterexample or an inconclusive search.','比较线性一致与顺序一致历史，查看合法顺序、失败或未判定。')),('evidence',L(lang,'Every baseline repetition: caller outcomes, committed effects, lease generations and recovery reads.','保存全部基线重复：调用者结果、已提交效果、租约代次与恢复读取。')),('reproduce',L(lang,'Download the standalone source. Run, inspect and modify three real experiment families on loopback.','下载独立源码，在回环环境执行、检查和修改三类真实实验。'))])
    return f'''<div class="hero"><div><div class="eyebrow">A COURSE IN DISTRIBUTED SYSTEMS / 01</div><h1>{title}</h1><p>{intro}</p><div class="actions"><a class="btn" href="01-assumptions.html">{L(lang,'Start the course','开始学习')} →</a><a class="btn secondary" href="checker.html">{L(lang,'Try a history','检查一段历史')}</a></div></div>{net}</div><div class="facts"><div><strong>07</strong><span>{L(lang,'Connected chapters','连贯章节')}</span></div><div><strong>03 × 03</strong><span>{L(lang,'Experiments × baseline repetitions','实验家族 × 基线重复')}</span></div><div><strong>etcd 3.6.6</strong><span>{L(lang,'Pinned implementation','固定实现版本')}</span></div><div><strong>1 host</strong><span>{L(lang,'Real processes, bounded claims','真实进程，有界结论')}</span></div></div><h2 class="section-title">{L(lang,'Build the concepts in order','按依赖关系建立概念')}</h2><p class="subtext">{L(lang,'Start with processes, files and request/response programming. No business-domain background is assumed. Chapters 1–3 build the model; 4–6 apply it; 7 ties the evidence together.','只需了解进程、文件和请求响应编程，不要求业务背景。1–3 章建立模型，4–6 章应用模型，7 章串起证据链。')}</p><div class="path">{cards}</div><div class="wide-note"><strong>{L(lang,'Know the scope before the result.','先知道范围，再看结果。')}</strong><p>{L(lang,'The cluster is three real processes on one host. Faults are owned process crashes/pauses and delayed application responses. The browser checker is a separate small model. Neither is a multi-host performance proof.','集群是同机三个真实进程；故障来自自己进程的崩溃/暂停和应用响应延迟。浏览器检查器是另一个小模型；两者都不能证明多机性能。')}</p></div><section class="tools"><h2 class="section-title">{L(lang,'Inspect. Change. Reproduce.','检查、修改、复现。')}</h2><p class="subtext">{L(lang,'Read without installing anything. Run the companion when you want to explore a different schedule.','阅读无需安装。需要探索不同执行顺序时，再运行配套代码。')}</p><div class="tool-grid">{tools}</div></section><section class="tools"><h2 class="section-title">{L(lang,'Connect the layers','连接不同层次')}</h2><p class="subtext">{L(lang,'Continue into local transactions, streaming state, computational recovery and runtime cancellation without conflating their guarantees.','继续学习本地事务、流式状态、计算恢复与运行时取消，同时保留各自的保证边界。')}</p><p>{' · '.join(f'<a href="{ORIGIN}/{s}/{lang}/">{n}</a>' for s,n in [('mysql-lab','MySQL Lab'),('stream-batch-lab','Streaming Lab'),('distributed-compute-lab','Compute Lab'),('java-runtime-lab','Java Runtime Lab')])}</p></section>'''

def checker(lang):
    return f'''<p class="lede">{L(lang,'Can these completed operations belong to one legal register execution?','这些已完成操作能否放进一次合法的寄存器执行？')}</p><div class="wide-note"><strong>{L(lang,'Illustrative model check — not real cluster telemetry','原理模型检查 — 不是集群实测')}</strong><p>{L(lang,'One integer register, initial 0. Reads return the current value; writes replace it. All operations are completed, each client is sequential, and intervals use one comparable clock. No pending/timeout calls, transactions, causality messages or leases.','单整数寄存器，初值 0。读返回当前值，写替换它。所有操作均已完成，每客户端顺序调用，区间处于可比的同一时钟。不支持未完成/超时调用、事务、因果消息或租约。')}</p></div><h2>{L(lang,'Choose a history','选择历史')}</h2><div class="control-row"><button class="secondary" data-fixture="concurrent">{L(lang,'Concurrent','并发')}</button><button class="secondary" data-fixture="stale">{L(lang,'Stale','旧值读')}</button><button class="secondary" data-fixture="impossible">{L(lang,'Unwritten value','未写过的值')}</button></div><label for="history">{L(lang,'Completed operations (JSON; value is write input or read result)','已完成操作（JSON；value 为写入值或读结果）')}</label><textarea id="history" spellcheck="false" aria-describedby="history-help"></textarea><p class="local-only" id="history-help">{L(lang,'id and client: nonempty strings. type: read/write. value: safe integer. start/end: finite numbers, start < end. Same-client intervals cannot overlap. Inputs stay in your browser; no storage or analytics.','id/client 为非空字符串；type 为 read/write；value 为安全整数；start/end 为有限数且 start < end；同客户端区间不得重叠。输入只在浏览器处理，不存储，不发送分析数据。')}</p><div class="control-row"><label for="model">{L(lang,'Model','模型')}<br><select id="model"><option value="linearizable">{L(lang,'Linearizable: real-time precedence','线性一致：保留真实时间先后')}</option><option value="sequential">{L(lang,'Sequential: per-client order','顺序一致：保留每客户端顺序')}</option></select></label><label for="budget">{L(lang,'Search states (1–100,000)','搜索状态数（1–100,000）')}<br><input id="budget" type="number" min="1" max="100000" value="50000"></label><button id="run">{L(lang,'Check history','检查历史')}</button><button id="download" class="secondary">{L(lang,'Export result','导出结果')}</button></div><p id="verdict" role="status" aria-live="polite"></p><svg id="timeline" class="timeline" role="img" aria-label="{L(lang,'Operation intervals: teal reads and rust writes','操作区间：青色读，红色写')}"></svg><pre id="output" aria-label="{L(lang,'Search report','搜索报告')}"></pre><h2>{L(lang,'How to read the answer','如何解释答案')}</h2><p>{L(lang,'PASS gives one witness order. FAIL means every legal order was exhausted under this model. INCONCLUSIVE means the 12-operation size cap or search budget was reached; it is never counted as a pass. INVALID means malformed or unsupported input. A passing finite history does not prove an implementation correct.','通过给出一个合法顺序；失败表示在该模型中穷尽全部合法顺序；未判定表示达到 12 操作上限或搜索预算，绝不算通过；输入无效表示格式或范围不支持。有限历史通过不等于实现被证明正确。')}</p><p>{L(lang,'The search enumerates topological orders of precedence edges and the register state, memoizing chosen-set/value pairs. Real-time precedence uses end ≤ next start. Sequential mode retains only same-client edges. See chapters 2–3 for interpretation and the downloaded source for the independent permutation-oracle tests.','搜索枚举前置关系的拓扑顺序和寄存器状态，按已选集合/当前值记忆。真实时间边使用 end ≤ 下一次 start；顺序一致模式只保留同客户端的边。解释见第 2–3 章；独立全排列基准测试在下载源码中。')}</p>'''

def evidence(lang,report):
    if not report:return '<p>Evidence not collected yet. Do not publish this build.</p>'
    rows=[]
    for r in report['repetitions']:
        q=r['quorum'];f=r['fencing'];cases=r['retry']['cases']
        rows.append(f'<tr><td>{r["repeat"]}</td><td>{q["before"]["leader"]} → {q["new_leader"]}</td><td>{q["one_unreachable"]["outcome"]}</td><td>{q["two_unreachable_write"]["outcome"]} / {q["two_unreachable_linearizable_read"]["outcome"]}</td><td>{cases[0]["final_counter"]} / {cases[1]["final_counter"]}</td><td>{f["A"]["token"]} &lt; {f["B"]["token"]}</td></tr>')
    sections=''
    names={'quorum':L(lang,'A · Leader crash and quorum loss','A · Leader 崩溃与多数派丢失'),'retry':L(lang,'B · Timeout after commit and deduplication','B · 提交后超时与去重'),'fencing':L(lang,'C · Lease expiry and stale writer','C · 租约过期与旧写入者')}
    explanations={
    'quorum':L(lang,'The acknowledged pre-crash value survives and the restarted member catches up. One unavailable follower still permits a successful write. With two followers paused, both write and default read return no success inside their deadlines. Inspect the eventual value of the unknown write separately.','故障前已确认值保留，重启节点完成追赶。一个 Follower 不可响应时仍能写入；暂停两个 Follower 时，写和默认读在截止时间内均未成功。超时写的最终值单独核对。'),
    'retry':L(lang,'Each first request commits, then its response is delayed. Both callers time out. A retry causes two effects without deduplication, one with the atomic operation key. Concurrent replays and changed-payload conflicts are included.','首个请求先提交再延迟响应，两种模式的调用者都超时。无去重重试产生两次效果，原子操作键模式只产生一次；记录包含并发重放和不同内容的冲突。'),
    'fencing':L(lang,'A is paused until the leased lock is observed absent. B obtains a larger create_revision and writes first. A resumes: plain mode accepts its stale value; fenced mode rejects it and retains B-current.','暂停 A，直到观测租约锁不存在。B 获得更大的 create_revision 并先写入。A 恢复后，无 fence 接受旧值，带 fence 拒绝并保留 B-current。')}
    for key in names:
        sections+=f'<section id="{key}"><h2>{names[key]}</h2><p>{explanations[key]}</p>'
        for r in report['repetitions']:
            d=r[key]
            if key=='quorum':summary=f'{d["before"]["leader"]} → {d["new_leader"]}; 1 down: {d["one_unreachable"]["outcome"]}; 2 down: {d["two_unreachable_write"]["outcome"]}; reconciled = {d["unknown_write_after_recovery"]}'
            elif key=='retry':summary=' → '.join(str(x['final_counter']) for x in d['cases'])+' (plain / dedup)'
            else:summary=f'tokens {d["A"]["token"]} &lt; {d["B"]["token"]}; plain = A-late; fenced = B-current'
            sections+=f'<div class="report"><span class="evidence-badge">REAL RUN / {r["repeat"]:02}</span><p>{summary}</p><details><summary>{L(lang,"Inspect complete exported record","检查完整导出记录")}</summary><pre>{esc(json.dumps(d,ensure_ascii=False,indent=2))}</pre></details></div>'
        sections+='</section>'
    digest=hashlib.sha256((ROOT/'results/experiments.json').read_bytes()).hexdigest()
    return f'''<p class="lede">{L(lang,'Recorded results from real processes. All three repetitions remain inspectable.','来自真实进程的保存结果，三次重复全部可检查。')}</p><p class="evidence-badge">REAL PROCESS EVIDENCE / {esc(report['recorded_at'])}</p><div class="wide-note"><strong>{L(lang,'Topology and conditions','拓扑与条件')}</strong><p>etcd 3.6.6 · {esc(report['runtime']['platform'])} · Python {esc(report['runtime']['python'])}</p><p>{L(lang,'Three loopback voting processes, separate WAL directories, one host. Actual process kill/pause and delayed HTTP responses. No packet partition, storage destruction or multi-host performance measurement. Durations use the orchestrator’s monotonic clock and include request round trips.','同机三个回环投票进程，各有独立 WAL。实际杀死/暂停进程并延迟 HTTP 响应；未做数据包分区、存储毁坏或多机性能测量。耗时使用编排者的单调时钟，包含请求往返。')}</p></div><div class="actions"><a class="btn" href="../results/experiments.json" download>{L(lang,'Download evidence JSON','下载证据 JSON')}</a><a class="btn secondary" href="../results/index.json">{L(lang,'Hash manifest','哈希清单')}</a></div><p class="hash">SHA-256: {digest}</p><table><thead><tr><th>{L(lang,'Repeat','重复')}</th><th>Leader</th><th>1 down</th><th>2 down write/read</th><th>plain / dedup</th><th>Fence tokens</th></tr></thead><tbody>{''.join(rows)}</tbody></table>{sections}<h2>{L(lang,'What remains unmeasured','尚未测量')}</h2><p>{L(lang,'These checks establish the asserted outcomes in this bounded schedule, not universal correctness or production capacity. Recovery uses the same durable directory; backup restore is not executed. The history workbench uses synthetic fixtures and does not certify these records. Raw logs remain local; this report contains only selected synthetic observations.','这些检查确认有界调度中的断言结果，不证明普遍正确性或生产容量。恢复保留原持久化目录，未执行备份还原。历史检查台使用合成样例，不认证这些记录。原始日志留本地，报告只包含选定合成观测。')}</p>'''

def references(lang):
    sources=[('Lamport, 1978','https://lamport.azurewebsites.net/pubs/time-clocks.pdf',L(lang,'Causality and logical clocks; chapter 2.','因果与逻辑时钟；第 2 章。')),('Herlihy & Wing, 1990','https://www.cs.cmu.edu/~wing/publications/HerlihyWing90.pdf',L(lang,'Operation histories and linearizability; chapters 2–3 and the workbench.','操作历史与线性一致；第 2–3 章和检查台。')),('Fischer, Lynch & Paterson, 1985','https://groups.csail.mit.edu/tds/papers/Lynch/jacm85.pdf',L(lang,'Asynchronous model and termination limits; chapter 1.','异步模型与终止限制；第 1 章。')),('Ongaro & Ousterhout, 2014','https://raft.github.io/raft.pdf',L(lang,'Raft extended paper; log safety, snapshots and client retries.','Raft 扩展论文；日志安全、快照与客户端重试。')),('Burrows, 2006 — Chubby','https://research.google/pubs/the-chubby-lock-service-for-loosely-coupled-distributed-systems/',L(lang,'Sequencers and delayed requests, §2.4; chapter 6.','Sequencer 与迟到请求，§2.4；第 6 章。')),('MIT 6.5840','https://pdos.csail.mit.edu/6.824/schedule.html',L(lang,'Further course study; this Lab is independent, not an MIT course copy.','后续课程学习；本 Lab 独立编写，不是 MIT 课程副本。'))]
    sources+=[('etcd 3.6 · '+name,link,L(lang,'Version-scoped implementation reference.','指定版本的实现参考。')) for name,link in [('API guarantees','https://etcd.io/docs/v3.6/learning/api_guarantees/'),('Failure modes','https://etcd.io/docs/v3.6/op-guide/failures/'),('JSON gateway','https://etcd.io/docs/v3.6/dev-guide/api_grpc_gateway/'),('API reference','https://etcd.io/docs/v3.6/dev-guide/api_reference_v3/'),('Recovery','https://etcd.io/docs/v3.6/op-guide/recovery/'),('FAQ','https://etcd.io/docs/v3.6/faq/'),('v3.6.6 release','https://github.com/etcd-io/etcd/releases/tag/v3.6.6')]]
    rows=''.join(f'<li><a href="{u}">{esc(n)}</a><p>{d}</p></li>' for n,u,d in sources)
    return f'''<p class="lede">{L(lang,'Original explanations, primary sources, and explicit boundaries.','原创讲解、原始来源与明确的边界。')}</p><p>{L(lang,'Sources checked for this edition on 2026-11-14. Papers and third-party figures are linked, not copied or bundled. Course diagrams and examples are original. The implementation is pinned to etcd 3.6.6; newer documentation or releases do not retroactively change the recorded run.','本版来源核查日期为 2026-11-14。论文与第三方图只链接，不复制或打包。课程图和例子为原创。实现固定 etcd 3.6.6；后来版本不改变保存运行的条件。')}</p><ol>{rows}</ol><h2>{L(lang,'Reading and experiment boundaries','阅读与实验边界')}</h2><p>{L(lang,'The course covers crash/recovery coordination, a single consensus group, completed single-register histories and a deliberately small downstream fence. It does not teach all of distributed systems: sharding, BFT, CRDT implementation, distributed garbage collection, production authentication, packet fault matrices and verified disaster restore remain extensions. No learning-effect measurement has been performed.','课程覆盖崩溃恢复协调、一个共识组、已完成的单寄存器历史，以及刻意缩小的下游 fence。它不覆盖整个分布式系统学科：分片、BFT、CRDT 实现、分布式垃圾回收、生产认证、数据包故障矩阵和经过验证的灾难还原均为扩展。未测量学习效果。')}</p><p>{L(lang,'The real-run report is generated from the selected assertions, with hashes for integrity. Timings are observations, not benchmarks with statistical power. The search checker can return inconclusive and does not consume unknown-outcome calls.','真实报告由指定断言生成，哈希用于完整性核查。耗时是观测值，不是具有统计效力的基准。搜索检查器可以报告未判定，不接收未知结果调用。')}</p>'''

def kit_files():
    names=['README.md','README.zh-CN.md','LICENSE','.gitignore','VALIDATION.md','course.json']
    paths=[ROOT/n for n in names]
    for folder,exts in [('lab',{'.py'}),('scripts',{'.py'}),('tests',{'.py','.mjs'}),('web',{'.css','.mjs'}),('docs',{'.html','.md'}),('results',{'.json'}),('.github/workflows',{'.yml'})]:
        paths.extend(p for p in (ROOT/folder).rglob('*') if p.is_file() and p.suffix in exts and '__pycache__' not in p.parts)
    return sorted(set(paths))
def main():
    if OUT.exists():shutil.rmtree(OUT)
    OUT.mkdir(parents=True);assets=OUT/'assets';assets.mkdir()
    for n in ('style.css','app.mjs','checker.mjs'):shutil.copy2(ROOT/'web'/n,assets/n)
    (assets/'icon.svg').write_text('<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 64 64"><rect width="64" height="64" rx="12" fill="#1e2c2c"/><path d="M32 12 12 48 52 48Z" stroke="#a7c1b1" fill="none" stroke-width="3"/><circle cx="32" cy="12" r="7" fill="#f7f5ee"/><circle cx="12" cy="48" r="7" fill="#a7c1b1"/><circle cx="52" cy="48" r="7" fill="#b84932"/></svg>')
    report=json.loads((ROOT/'results/experiments.json').read_text()) if (ROOT/'results/experiments.json').exists() else None
    for lang in ('en','zh'):
        folder=OUT/lang;folder.mkdir()
        bodies={'index':home(lang),'checker':checker(lang),'evidence':evidence(lang,report),'references':references(lang)}
        for s in [x['slug'] for x in COURSE]+['reproduce']:bodies[s]=(ROOT/'docs'/f'{s}.{lang}.html').read_text()
        for slug,body in bodies.items():(folder/(slug+'.html')).write_text(frame(lang,slug,body))
    (OUT/'index.html').write_text('<!doctype html><html lang="en-US"><head><meta charset="utf-8"><meta http-equiv="refresh" content="0;url=en/"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Distributed Systems Lab</title><link rel="canonical" href="'+url('en','index')+'"></head><body><a href="en/">English</a> · <a href="zh/">中文</a></body></html>')
    shutil.copytree(ROOT/'results',OUT/'results')
    downloads=OUT/'downloads';downloads.mkdir()
    with zipfile.ZipFile(downloads/'distributed-systems-lab.zip','w',zipfile.ZIP_DEFLATED) as z:
        for p in kit_files():z.write(p,'distributed-systems-lab/'+str(p.relative_to(ROOT)))
    sitemap='<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'+''.join('<url><loc>'+url(l,s)+'</loc></url>' for l in ('en','zh') for s in TITLES)+'</urlset>'
    (OUT/'sitemap.xml').write_text(sitemap)
    files=[{'path':str(p.relative_to(OUT)),'sha256':hashlib.sha256(p.read_bytes()).hexdigest()} for p in sorted(OUT.rglob('*')) if p.is_file()]
    (OUT/'export-manifest.json').write_text(json.dumps({'schema':1,'export':'allowlisted distributed-systems-lab','files':files},indent=2)+'\n')
    print(f'Built {len(files)} allowlisted files, bilingual course and standalone kit.')
if __name__=='__main__':main()
